select 'car_rental', 'Shift Car Rental – Sharjah', 'Shift Car Rental – Sharjah', 'الشارقة', null, '+971565492707', 'https://www.shiftcarrental.com/AE', 2008, 'فرع شيفت لتأجير السيارات في الشارقة، التابعة لمجموعة عبدالواحد الرستماني.', 'https://shiftcarrental.com/AE/rent-a-car-in-sharjah', 'شيفت لتأجير السيارات تعمل تحت مظلة AWR Automotive ذراع قطاع السيارات في مجموعة عبدالواحد الرستماني، وتقدم التأجير اليومي والأسبوعي والشهري والتأجير طويل الأجل. يذكر الموقع أن الشركة تعمل في تأجير السيارات في الدولة منذ 2008، وأنها حاصلة على شهادة ISO وجائزة الشيخ خليفة للامتياز.', 'https://www.shiftcarrental.com/shiftlease/assets/images/header-logo.svg', null, null, null, array['تأجير يومي وأسبوعي وشهري', 'تأجير طويل الأجل (ليسنغ) للأفراد والشركات', 'سيارات صغيرة ودفع رباعي وفاخرة وتجارية', 'إدارة أساطيل الشاحنات والفانات', 'توصيل واستلام السيارة من موقع العميل']::text[], null, true
