select 'engineering', 'Arif & Bintoak Consulting Architects & Engineers', 'Arif & Bintoak Consulting Architects & Engineers', 'دبي', 'الكرامة', '+97143372888', 'https://www.artoak.com', null, 'مكتب استشارات معمارية وهندسية في دبي يقدم التصميم المعماري والإنشائي والإشراف على التنفيذ.', 'https://www.artoak.com/about', 'فريق من المهندسين والمعماريين الاستشاريين يقدّم خدماته منذ أكثر من 40 عامًا. تشمل خدماته العمارة والهندسة الإنشائية وهندسة الكهروميكانيك والتصميم الداخلي وحساب الكميات والإشراف على التنفيذ وإدارة العقود. نفّذ مشاريع تتراوح بين تجديد المساكن الصغيرة والمشاريع التجارية الكبيرة.', null, 'artoak@eim.ae', 'مبنى عارف وبن طوق، الطابق الثالث، شارع زعبيل، الكرامة، ص.ب 3670، دبي', null, array['ند الشبا مول', 'مباني ضمان', 'مشاريع سكنية', 'مشاريع رعاية صحية', 'مشاريع فندقية']::text[], 'يقود المكتب الشريكان نبيل عارف وعبدالله بن طوق.', true
