select 'engineering', 'AESG', 'AESG', 'دبي', 'جبل علي (بوابة ابن بطوطة)', '+97144326242', 'https://aesg.com', null, 'شركة استشارات هندسية متخصصة في الاستدامة وهندسة المباني والواجهات والسلامة من الحريق.', 'https://aesg.com/offices/united-arab-emirates/', 'شركة استشارات هندسية واستدامة لها مقار في دبي وأبوظبي ولندن والرياض وسنغافورة. تقدم خدمات البيئة والاستدامة وهندسة الواجهات والسلامة من الحريق وخدمات المباني (MEPF) والصوتيات، إضافة إلى إدارة تسليم المشاريع والتكاليف والتشغيل التجريبي.', 'https://aesg.com/wp-content/uploads/2026/02/AESG_Brandmark_RGB-300x87.webp', null, '601-608، ذا أوفيسز في بوابة ابن بطوطة، جبل علي 1 - فيليج، ص.ب 2556، دبي', null, array['آي سي دي بروكفيلد بليس (دبي)', 'مصدر MC2 (أبوظبي)', 'المقر الرئيسي لبيئة (الشارقة)', 'محطة حتا للطاقة الكهرومائية']::text[], null, true
