select 'immigration', 'Fly High Abroad', 'Fly High Abroad', 'الشارقة', 'المجاز 3', null, 'https://www.flyhigh-abroad.com', null, 'المقر الرئيسي لشركة فلاي هاي أبرود لاستشارات الهجرة في منطقة المجاز بالشارقة.', 'https://www.flyhigh-abroad.com/citizenship-by-investment', 'فلاي هاي أبرود مكتب استشارات هجرة وتأشيرات يقدّم خدمات الهجرة للمهارات والدراسة والأعمال والجنسية عن طريق الاستثمار، وله مكتب في كندا. ويشير موقعه إلى أن مقره الرئيسي في الشارقة.', 'https://www.flyhigh-abroad.com/wp-content/uploads/2021/06/flylogo521.png', 'info@flyhigh-abroad.com', 'مكتب 1402، فيرست تاور، المجاز 3، الشارقة', null, array['الهجرة للمهارات', 'الجنسية عن طريق الاستثمار', 'تأشيرات الأعمال', 'خدمات ما قبل الوصول']::text[], 'المؤسس والرئيس التنفيذي أبهيشيك ماهاجان.', true
where not exists (select 1 from public.service_providers where category = 'immigration' and emirate = 'الشارقة' and lower(coalesce(name_en, name_ar)) = lower('Fly High Abroad'));
