select 'immigration', 'WWICS - Global Strategic Management Consultancy LLC', 'WWICS - Global Strategic Management Consultancy LLC', 'الشارقة', 'القاسمية', '+97166780127', 'https://www.wwicsgroup.com', null, 'مكتب تابع لمجموعة WWICS لاستشارات الهجرة في منطقة القاسمية بالشارقة.', 'https://www.wwicsgroup.com/contact-us/', 'مكتب في الشارقة تابع لمجموعة WWICS لاستشارات الهجرة والتأشيرات. وتذكر المجموعة أن مكاتبها القانونية تأسست عام 1993.', 'https://wwicsgroup.com/wp-content/uploads/2020/06/wwics_logo.png', 'sharjah@immigrationwwics.com', 'مكتب 103، الطابق الأول، بناية الفيصل 2، 23 شارع عبدالله بن رواحة، النّد، القاسمية، الشارقة 61157 (مقابل مخابز شمسين)', null, '{}'::text[], null, true
