select 'recruitment', 'Inspire Selection', 'Inspire Selection', 'دبي', 'وسط مدينة دبي', '+971 4 368 0852', 'https://www.inspireselection.com', null, 'شركة توظيف متخصصة في الوظائف المهنية مقرها وسط مدينة دبي.', 'https://www.inspireselection.com/contact-us', 'إنسباير سيليكشن شركة توظيف متخصصة في شغل الوظائف المهنية. يضم فريقها مستشاري توظيف بخبرات تتراوح بين 10 و25 عامًا، وتركز على بناء علاقات طويلة الأمد مع العملاء والمرشحين.', 'https://cdn.prod.website-files.com/653a29e472ec5dfeaf5d3ff5/65426a174ea05fb8d982ed0c_primary%20logo%20colour.svg', 'info@inspireselection.com', 'الطابق 14، برج بوليفارد بلازا 1، شارع إعمار بوليفارد، وسط مدينة دبي، ص.ب 334155، دبي', null, array['توظيف في المالية والمحاسبة', 'توظيف في البنوك والخدمات المالية', 'توظيف المبيعات والتسويق للسلع الاستهلاكية', 'توظيف سلاسل الإمداد والخدمات اللوجستية', 'توظيف الدفاع والتصنيع والصناعة']::text[], 'فريق من مستشاري التوظيف المحترفين بخبرة 10 إلى 25 عامًا لكل منهم.', true
where not exists (select 1 from public.service_providers where category = 'recruitment' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Inspire Selection'));
