select 'recruitment', 'Ontime Manpower Supply L.L.C', 'Ontime Manpower Supply L.L.C', 'دبي', 'مجمع دبي للاستثمار', '+971 4 256 6333', 'https://ontimeuae.com', null, 'شركة توريد عمالة وحلول توظيف في دبي مرخصة من وزارة الموارد البشرية والتوطين منذ 2011.', 'https://ontimeuae.com/manpower-supply-in-sharjah/', 'أونتايم لتوريد العمالة ش.ذ.م.م شركة مقرها مجمع دبي للاستثمار، وتذكر أنها مرخصة من وزارة الموارد البشرية والتوطين منذ 2011 وأنها أول من حصل على رخصة توريد العمالة عند الطلب. تقدم حلول العمالة عند الطلب والتوظيف التنفيذي وخدمات صاحب العمل المسجّل وتعهيد عمليات التوظيف.', 'https://ontimeuae.com/wp-content/uploads/2025/09/ontime-logo-03.svg', 'info@ontimeuae.com', 'مكتب 156، مركز الأعمال الأوروبي، مجمع دبي للاستثمار، دبي', null, array['حلول العمالة عند الطلب', 'التوظيف التنفيذي', 'خدمات المندوبين', 'خدمات صاحب العمل المسجّل (EOR)', 'تعهيد عمليات التوظيف (RPO)']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'recruitment' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Ontime Manpower Supply L.L.C'));
