select 'recruitment', 'Sundus Recruitment Services LLC', 'Sundus Recruitment Services LLC', 'دبي', 'برشا هايتس', '+971 4 430 9501', 'https://www.sundusglobal.com', null, 'مكتب دبي لشركة سندس لخدمات التوظيف وتوريد القوى العاملة في برشا هايتس.', 'https://www.sundusglobal.com/manpower-supply-company-sharjah', 'سندس لخدمات التوظيف شركة مقرها الرئيسي في أبوظبي ولها في دبي مكاتب في برشا هايتس والمنطقة الحرة بجبل علي ومدينة دبي للتعهيد. تقدم التوظيف المؤقت والدائم والبحث عن التنفيذيين.', null, null, '11-E02، أبراج آي رايز، برشا هايتس، شارع حصة، دبي', null, array['التوظيف المؤقت', 'التوظيف الدائم', 'البحث عن التنفيذيين', 'التوظيف الدولي']::text[], null, true
