select 'recruitment', 'World Star Manpower Solutions', 'World Star Manpower Solutions', 'أبوظبي', null, '+971 2 666 1110', 'https://www.worldstarmanpower.ae', 2008, 'شركة توريد عمالة في أبوظبي تأسست عام 2008 وتذكر أنها معتمدة من وزارة الموارد البشرية والتوطين.', 'https://www.worldstarmanpower.ae/about-us/', 'وورلد ستار لحلول القوى العاملة تأسست في أبوظبي عام 2008 ضمن مجموعة وورلد ستار القابضة، وتعرض شهادة اعتماد من وزارة الموارد البشرية والتوطين. توفر عمالة ماهرة في الأعمال المدنية والكهروميكانيكية والتشطيبات والتنظيف بعقود يومية وشهرية ومشاريع، وافتتحت مكتبًا في دبي عام 2016.', 'https://www.worldstarmanpower.ae/wp-content/uploads/2026/05/Untitled-design-2026-05-19T171134.735.png', 'inquiry@worldstarmanpower.ae', null, 'https://www.google.com/maps/place/World+Star+Manpower+Solutions+Abu+Dhabi/@24.3569504,54.5216433,17z/data=!4m8!3m7!1s0x3e5e463714d01863:0x807dea87ce50720a!8m2!3d24.3777446!4d54.5236091!9m1!1b1!16s%2Fg%2F12m8_1k9k', array['متحف اللوفر', 'قطار الاتحاد', 'مطار أبوظبي', 'توريد عمالة الأعمال الكهروميكانيكية', 'توريد عمالة التشطيبات والتنظيف']::text[], 'يرأس المجموعة نشاد رئيسًا لمجلس الإدارة وحسينة نشاد مديرةً عامة، وتذكر أن لديها أكثر من 12,000 عامل.', true
where not exists (select 1 from public.service_providers where category = 'recruitment' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('World Star Manpower Solutions'));
