select 'recruitment', 'Al Sahara Group', 'Al Sahara Group', 'عجمان', 'الراشدية 1', '+971 6 745 0712', 'https://alsaharagroup.com', null, 'شركة توريد عمالة في عجمان توفر عمالة البناء والكهروميكانيك والضيافة والتنظيف.', 'https://alsaharagroup.com/', 'مجموعة الصحراء شركة توريد عمالة مقرها برج هورايزن في عجمان وتخدم جميع الإمارات. توفر عمالة البناء والأعمال الكهروميكانيكية وطواقم الضيافة والتنظيف وعمال المصانع والتغليف.', 'https://alsaharagroup.com/images/logos.png', 'info@alsaharagroup.com', 'شقة 308، برج هورايزن D، قطاع سيتي سنتر، الراشدية 1، عجمان، ص.ب 239028', null, array['عمالة البناء', 'عمالة الأعمال الكهروميكانيكية', 'طواقم الضيافة والتدبير الفندقي', 'عمالة المصانع والتغليف', 'عمالة التنظيف']::text[], 'يقودها الشيخ شاهين بصفته الرئيس التنفيذي، وتذكر أن لديها نحو 300 عامل.', true
where not exists (select 1 from public.service_providers where category = 'recruitment' and emirate = 'عجمان' and lower(coalesce(name_en, name_ar)) = lower('Al Sahara Group'));

-- إعادة تفعيل حماية الإغراق
do $$ begin
  if exists (select 1 from pg_trigger where tgname = 'aq_rate_limit_service_providers') then
    alter table public.service_providers enable trigger aq_rate_limit_service_providers;
  end if;
end $$;


-- للتأكد: عدد الشركات في كل قسم وإمارة
select category, emirate, count(*) from public.service_providers where is_active group by 1, 2 order by 1, 3 desc;
